def parse_minutes(text):
    minutes = int(text)
    if minutes < 0:
        raise ValueError("minutes must be nonnegative")
    return minutes

for text in ["15", "-2"]:
    try:
        print(parse_minutes(text))
    except ValueError as error:
        print(f"Invalid: {error}")

# Expected output:
# 15
# Invalid: minutes must be nonnegative

