import unittest

def count_completed(tasks):
    return sum(1 for task in tasks if task["done"])

class TaskTests(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(count_completed([]), 0)
    def test_mixed(self):
        self.assertEqual(count_completed([{"done": True}, {"done": False}]), 1)

suite = unittest.defaultTestLoader.loadTestsFromTestCase(TaskTests)
result = unittest.TestResult()
suite.run(result)
print(result.testsRun)
print(result.wasSuccessful())

