def totals_by_topic(log):
    totals = {}
    for session in log:
        topic = session["topic"]
        totals[topic] = totals.get(topic, 0) + session["minutes"]
    return totals

log = [{"topic": "Python", "minutes": 25}, {"topic": "Reading", "minutes": 10}, {"topic": "Python", "minutes": 15}]
print(totals_by_topic(log))
